/*
 * AgentRogue: on-chain run records (test).
 * At game over, show a ready-to-run `baw contract-call` command so the player's agent
 * can record the run on AgentRogueRecords (BNB Chain). Non-blocking overlay.
 */
import { encodeFunctionData, encodePacked, keccak256, parseAbi, toHex } from "viem";

export const RECORDS_ADDRESS = "0xE011596E90c90cCa54b3357ed3F15A1Cd958D060" as const;
const ABI = parseAbi(["function submitRun(uint32 wave, uint8 mode, bool victory, bytes32 seed, bytes32 runHash)"]);
const MODE_NAMES = ["经典", "无尽", "无尽·传说", "挑战", "每日"];

export interface RunInfo {
  wave: number;
  mode: number;
  victory: boolean;
  seed: string;
}

export function buildSubmit(wallet: string, run: RunInfo) {
  const seed = keccak256(toHex(run.seed || "none"));
  const runHash = keccak256(
    encodePacked(["address", "bytes32", "uint32", "uint64"], [wallet as `0x${string}`, seed, run.wave, BigInt(Date.now())]),
  );
  const data = encodeFunctionData({
    abi: ABI,
    functionName: "submitRun",
    args: [run.wave, run.mode & 0xff, run.victory, seed, runHash],
  });
  const cmd = `baw contract-call preview --binanceChainId 56 --from ${wallet} --to ${RECORDS_ADDRESS} --value 0 --inputData ${data} --json`;
  return { data, cmd };
}

export function showSubmit(run: RunInfo): void {
  const wallet: string | undefined = (window as any).agentWallet;
  if (!wallet || run.wave < 1 || document.getElementById("agent-records")) {
    return;
  }
  const { cmd } = buildSubmit(wallet, run);
  const el = document.createElement("div");
  el.id = "agent-records";
  el.style.cssText =
    "position:fixed;right:18px;bottom:18px;z-index:9998;width:min(520px,calc(100% - 36px));background:#1f1a2c;color:#fff;border:4px solid #15121c;border-radius:24px;padding:18px;font:500 14px 'Rubik','PingFang SC',sans-serif;box-shadow:0 8px 0 #15121c,0 24px 50px rgba(0,0,0,.5);animation:ar-in .6s cubic-bezier(.34,1.56,.64,1) backwards";
  if (!document.getElementById("ar-style")) {
    const st = document.createElement("style");
    st.id = "ar-style";
    st.textContent =
      "@font-face{font-family:'Titan One';src:url('./ink-fonts/TitanOne-latin.woff2') format('woff2');font-display:swap}@font-face{font-family:'Rubik';src:url('./ink-fonts/Rubik-latin.woff2') format('woff2');font-weight:400 900;font-display:swap}" +
      "@keyframes ar-in{from{opacity:0;transform:translateY(40px) scale(.9) rotate(-3deg)}}#agent-records button,#agent-records a.b{border:3px solid #15121c;border-radius:14px;padding:8px 16px;cursor:pointer;font:400 15px 'Titan One','PingFang SC',sans-serif;box-shadow:0 4px 0 #15121c;text-decoration:none;transition:transform .35s cubic-bezier(.34,1.56,.64,1)}#agent-records button:hover,#agent-records a.b:hover{transform:translateY(-2px) scale(1.05)}";
    document.head.appendChild(st);
  }
  el.innerHTML = `
<div style="display:flex;justify-content:space-between;align-items:center">
  <b style="color:#ff8a14;font:400 22px 'Titan One','PingFang SC',sans-serif;-webkit-text-stroke:.16em #15121c;paint-order:stroke fill;text-shadow:0 2px 0 #15121c">把这局记上链</b>
  <span id="ar-x" style="cursor:pointer;color:#c3bdd6;font-size:20px">✕</span>
</div>
<p style="margin:6px 0;color:#c3bdd6">第 ${run.wave} 波 · ${MODE_NAMES[run.mode] ?? `模式${run.mode}`} · ${run.victory ? "通关" : "结束"}。让 agent 执行下面的命令，再执行 <code>baw contract-call execute --requestId &lt;requestId&gt; --json</code>。只花少量 gas，不转任何代币。</p>
<textarea readonly style="width:100%;box-sizing:border-box;height:90px;background:#15121c;color:#fff;border:3px solid #2c2540;border-radius:12px;padding:8px;font:12px ui-monospace,Menlo,monospace">${cmd}</textarea>
<div style="margin-top:8px;display:flex;gap:8px">
  <button id="ar-copy" style="background:#ff8a14;color:#15121c">复制命令</button>
  <a class="b" href="./leaderboard.html" target="_blank" style="background:#2f5bff;color:#fff">排行榜</a>
</div>`;
  document.body.appendChild(el);
  el.querySelector<HTMLElement>("#ar-x")!.onclick = () => el.remove();
  el.querySelector<HTMLElement>("#ar-copy")!.onclick = async () => {
    const ta = el.querySelector("textarea")!;
    try {
      await navigator.clipboard.writeText(ta.value);
    } catch {
      ta.select();
      document.execCommand("copy");
    }
    el.querySelector<HTMLElement>("#ar-copy")!.textContent = "已复制";
  };
}
